CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`email` VARCHAR(191) NOT NULL,`passwordHash` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `User_email_key`(`email`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Project` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`description` TEXT NULL,`ownerId` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `Project_ownerId_idx`(`ownerId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Task` (`id` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`description` TEXT NULL,`status` ENUM('TODO','IN_PROGRESS','DONE') NOT NULL DEFAULT 'TODO',`priority` ENUM('LOW','MEDIUM','HIGH') NOT NULL DEFAULT 'MEDIUM',`dueDate` DATETIME(3) NULL,`projectId` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `Task_projectId_status_idx`(`projectId`,`status`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Project` ADD CONSTRAINT `Project_ownerId_fkey` FOREIGN KEY (`ownerId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Task` ADD CONSTRAINT `Task_projectId_fkey` FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

